-- Generated by generate_rift_survey.py from the rift_*.csv sheets in data/d3 (diablocraft-7vhj); never edit.
-- The survey of the rift dungeons (docs/proposals/monster-spawning.md 3.5.1, Part S0): areas, anchors, stock patrol routes,
-- the natives the spawner refuses and each dungeon's exit point. Dev edits come home through --export, then a new migration.
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS `dc_rift_area` (`dungeon` VARCHAR(64) NOT NULL, `area` INT UNSIGNED NOT NULL, `tag` CHAR(1) NOT NULL, `natives` INT UNSIGNED NOT NULL, `density_min` INT UNSIGNED NULL, `density_max` INT UNSIGNED NULL, `nospawn` TINYINT UNSIGNED NOT NULL, `source` VARCHAR(8) NOT NULL, PRIMARY KEY (`dungeon`, `area`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
DELETE FROM `dc_rift_area` WHERE `dungeon` NOT IN ('Un''Goro Crater');
CREATE TABLE IF NOT EXISTS `dc_rift_anchor` (`dungeon` VARCHAR(64) NOT NULL, `anchor` INT UNSIGNED NOT NULL, `area` INT UNSIGNED NOT NULL, `x` DOUBLE NOT NULL, `y` DOUBLE NOT NULL, `z` DOUBLE NOT NULL, `o` DOUBLE NOT NULL, `pack_size` INT UNSIGNED NOT NULL, `native_guid` INT UNSIGNED NULL, `native_entry` INT UNSIGNED NULL, `entry_walk_yards` DOUBLE NULL, `source` VARCHAR(8) NOT NULL, PRIMARY KEY (`dungeon`, `anchor`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
DELETE FROM `dc_rift_anchor` WHERE `dungeon` NOT IN ('Un''Goro Crater');
CREATE TABLE IF NOT EXISTS `dc_rift_route` (`dungeon` VARCHAR(64) NOT NULL, `path_id` INT UNSIGNED NOT NULL, `anchor` INT UNSIGNED NOT NULL, `start_x` DOUBLE NOT NULL, `start_y` DOUBLE NOT NULL, `start_z` DOUBLE NOT NULL, `points` INT UNSIGNED NOT NULL, `length_yards` DOUBLE NOT NULL, `source` VARCHAR(8) NOT NULL, PRIMARY KEY (`dungeon`, `path_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
DELETE FROM `dc_rift_route` WHERE `dungeon` NOT IN ('Un''Goro Crater');
CREATE TABLE IF NOT EXISTS `dc_rift_native_filter` (`map_id` INT UNSIGNED NOT NULL, `spawn_guid` INT UNSIGNED NOT NULL, `dungeon` VARCHAR(64) NOT NULL, `anchor` INT UNSIGNED NOT NULL, PRIMARY KEY (`map_id`, `spawn_guid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
DELETE FROM `dc_rift_native_filter` WHERE `dungeon` NOT IN ('Un''Goro Crater');
CREATE TABLE IF NOT EXISTS `dc_rift_exit_point` (`dungeon` VARCHAR(64) NOT NULL, `x` DOUBLE NOT NULL, `y` DOUBLE NOT NULL, `z` DOUBLE NOT NULL, `o` DOUBLE NOT NULL, `walk_yards` DOUBLE NULL, `source` VARCHAR(8) NOT NULL, PRIMARY KEY (`dungeon`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
DELETE FROM `dc_rift_exit_point` WHERE `dungeon` NOT IN ('Un''Goro Crater');
